/** 归元合脉的选择校验与 MVU 数据迁移逻辑。该模块不依赖酒馆或 Vue，便于单元测试。 */

export interface FusionSelection {
  name: string;
  source: '功法' | '初始功法';
  technique: {
    已学习?: unknown;
    层级?: unknown;
    [key: string]: unknown;
  };
}

export interface FusionValidation {
  valid: boolean;
  reason?: string;
  targetLevel?: number;
}

export interface FusionDataShape {
  功法: Record<string, Record<string, any>>;
  初始功法: Record<string, Record<string, any>>;
}

/** 将 AI 常见的“无前置”占位值转换为真实的触发功法名称。 */
export function normalizePrerequisite(value: unknown, triggerName: string): string {
  const prerequisite = String(value ?? '').trim();
  const emptyMarkers = new Set(['', '无', '无前置', '暂无', 'none', 'null', 'nil', 'n/a']);
  return emptyMarkers.has(prerequisite.toLowerCase()) ? triggerName : prerequisite;
}

/** 校验融合选择，并计算融合结果应使用的层级。 */
export function validateFusionSelection(selected: readonly FusionSelection[], maxLevel = 12): FusionValidation {
  if (selected.length < 2) return { valid: false, reason: '至少选择2门已学习功法' };
  if (selected.length > 5) return { valid: false, reason: '最多选择5门功法' };

  const names = selected.map(item => item.name.trim());
  if (names.some(name => !name)) return { valid: false, reason: '功法名称不能为空' };
  if (new Set(names).size !== names.length) return { valid: false, reason: '不能重复选择同一门功法' };

  const levels = selected.map(item => Number(item.technique?.层级));
  if (selected.some(item => item.technique?.已学习 !== true)) {
    return { valid: false, reason: '只能融合已学习功法' };
  }
  if (levels.some(level => !Number.isFinite(level) || level < 1)) {
    return { valid: false, reason: '功法层级无效' };
  }

  const highestLevel = Math.max(...levels);
  if (highestLevel >= maxLevel) return { valid: false, reason: `选中功法已达到最高层级${maxLevel}` };
  return { valid: true, targetLevel: highestLevel + 1 };
}

/** 删除被融合功法，写入新功法，并将后置功法的前置引用改到新功法。 */
export function applyFusionToData(
  data: FusionDataShape,
  selectedNames: readonly string[],
  fusedName: string,
  fusedTechnique: Record<string, any>,
): { removed: string[]; rewired: number } {
  const names = [...new Set(selectedNames.map(name => name.trim()).filter(Boolean))];
  if (names.length < 2) throw new Error('至少需要两门功法才能融合');
  if (!fusedName.trim()) throw new Error('融合功法名称不能为空');

  const selected = new Set(names);
  const existingOutsideSelection = Object.prototype.hasOwnProperty.call(data.功法, fusedName) && !selected.has(fusedName);
  const existingInitialOutsideSelection =
    Object.prototype.hasOwnProperty.call(data.初始功法, fusedName) && !selected.has(fusedName);
  if (existingOutsideSelection || existingInitialOutsideSelection) throw new Error('融合结果名称与现有功法重复');

  let rewired = 0;
  for (const collection of [data.功法, data.初始功法]) {
    for (const technique of Object.values(collection)) {
      if (technique && selected.has(String(technique.前置功法 ?? ''))) {
        technique.前置功法 = fusedName;
        rewired += 1;
      }
    }
  }

  for (const name of names) {
    delete data.功法[name];
    delete data.初始功法[name];
  }
  data.功法[fusedName] = { ...fusedTechnique, 已学习: true, 前置功法: fusedTechnique.前置功法 ?? '' };

  return { removed: names, rewired };
}
